  3069  long long hts_parse_decimal(const char *str, char **strend, int flags)
  3070  {
  3071      long long n = 0;
  3072      int decimals = 0, e = 0, lost = 0;
  3073      char sign = '+', esign = '+';
  3074      const char *s;
  3075
  3076      while (isspace_c(*str)) str++;
  3077      s = str;
  3078
  3079      if (*s == '+' || *s == '-') sign = *s++;
  3080      while (*s)
  3081          if (isdigit_c(*s)) n = push_digit(n, *s++);
  3082          else if (*s == ',' && (flags & HTS_PARSE_THOUSANDS_SEP)) s++;
  3083          else break;
  3084
  3085      if (*s == '.') {
  3086          s++;
  3087          while (isdigit_c(*s)) decimals++, n = push_digit(n, *s++);
  3088      }
  3089
  3090      if (*s == 'E' || *s == 'e') {
  3091          s++;
  3092          if (*s == '+' || *s == '-') esign = *s++;
  3093          while (isdigit_c(*s)) e = push_digit(e, *s++);
  3094          if (esign == '-') e = -e;
  3095      }
  3096
  3097      switch (*s) {
  3098      case 'k': case 'K': e += 3; s++; break;
  3099      case 'm': case 'M': e += 6; s++; break;
  3100      case 'g': case 'G': e += 9; s++; break;
  3101      }
  3102
  3103      e -= decimals;
  3104      while (e > 0) n *= 10, e--;
  3105      while (e < 0) lost += n % 10, n /= 10, e++;
  3106
  3107      if (lost > 0) {
  3108          hts_log_warning("Discarding fractional part of %.*s", (int)(s - str), str);
  3109      }
  3110
  3111      if (strend) {
  3112          *strend = (char *)s;
  3113      } else if (*s) {
  3114          if ((flags & HTS_PARSE_THOUSANDS_SEP) || (!(flags & HTS_PARSE_THOUSANDS_SEP) && *s != ','))
  3115              hts_log_warning("Ignoring unknown characters after %.*s[%s]", (int)(s - str), str, s);
  3116      }
  3117
  3118      return (sign == '+')? n : -n;
  3119  }
